const screens=[...document.querySelectorAll('.screen')];
let loadingTimer;
function go(id){clearTimeout(loadingTimer);screens.forEach(s=>s.classList.toggle('active',s.id===id));document.querySelectorAll('.progress button').forEach(b=>b.classList.toggle('current',b.dataset.go===id));const title=document.querySelector(`#${id} h1`);title.setAttribute('tabindex','-1');title.focus({preventScroll:true});window.scrollTo({top:0,behavior:'smooth'});}
document.querySelectorAll('[data-go]').forEach(b=>b.addEventListener('click',()=>go(b.dataset.go)));
document.querySelectorAll('[data-answer]').forEach(b=>b.addEventListener('click',()=>{const yes=b.dataset.answer==='yes';document.getElementById('reply').hidden=false;document.getElementById('reply-title').textContent=yes?'That little smile made my day ♡':'Then here’s one more little hug ♡';document.getElementById('reply-copy').textContent=yes?'Mission accomplished. The cat is very proud.':'It’s okay. You don’t have to smile on command. I’m still glad you’re here.';document.getElementById('send-answer').href=`mailto:glaisa06292004@gmail.com?subject=${encodeURIComponent('A little smile — my answer')}&body=${encodeURIComponent(yes?'Yes, you made me smile even a little! ♡ Thank you for the lovely surprise.':'Not yet, but thank you for thinking of me and for the little surprise. ♡')}`;document.querySelectorAll('[data-answer]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));}));
loadingTimer=setTimeout(()=>go('welcome'),3200);
